<?php
namespace App\Services;
use App\Models\{ShippingMethod,ShippingRate};
use Illuminate\Validation\ValidationException;
class ShippingRateService {
 public function quote(int $subtotal,int $weight,array $address,?string $code=null): array { $subtotal=max(0,$subtotal);$weight=max(0,$weight);$now=now();$methods=ShippingMethod::with(['rates'=>fn($q)=>$q->where('is_enabled',true)->where(fn($x)=>$x->whereNull('effective_from')->orWhere('effective_from','<=',$now))->where(fn($x)=>$x->whereNull('effective_until')->orWhere('effective_until','>=',$now))])->where('is_enabled',true)->orderBy('sort_order')->get();$quotes=[];foreach($methods as $method){if($code&&$method->code!==$code)continue;if($method->min_order_toman!==null&&$subtotal<$method->min_order_toman)continue;if($method->max_order_toman!==null&&$subtotal>$method->max_order_toman)continue;if($method->max_weight_grams!==null&&$weight>$method->max_weight_grams)continue;if($method->requires_address&&empty($address['city_code'])&&$method->code!=='pickup')continue;$rates=$method->rates->filter(fn($r)=>($r->min_weight_grams===null||$weight>=$r->min_weight_grams)&&($r->max_weight_grams===null||$weight<=$r->max_weight_grams)&&($r->min_order_toman===null||$subtotal>=$r->min_order_toman)&&($r->max_order_toman===null||$subtotal<=$r->max_order_toman)&&($r->province_code===null||$r->province_code===($address['province_code']??null))&&($r->city_code===null||$r->city_code===($address['city_code']??null)))->sortBy(fn($r)=>[$r->priority,$r->city_code?2:0,$r->province_code?1:0,$r->id])->last();$fee=(int)($rates?->fee_toman??$method->base_fee_toman);if($rates&&$rates->free_over_toman!==null&&$subtotal>=$rates->free_over_toman)$fee=0;if($rates&&$rates->weight_step_grams>0&&$weight>$rates->weight_step_grams)$fee+=(int)ceil(($weight-$rates->weight_step_grams)/$rates->weight_step_grams)*(int)$rates->weight_surcharge_toman;if($method->code==='pickup')$fee=0;$quotes[]=['method'=>$method,'fee_toman'=>max(0,$fee),'estimated_delivery'=>$method->estimated_delivery,'snapshot'=>['method_code'=>$method->code,'method_name'=>$method->name,'fee_toman'=>max(0,$fee),'subtotal_toman'=>$subtotal,'weight_grams'=>$weight,'province_code'=>$address['province_code']??null,'city_code'=>$address['city_code']??null,'rate_id'=>$rates?->id,'rate_priority'=>$rates?->priority]];}if(!$quotes)throw ValidationException::withMessages(['shipping_method'=>'برای این مقصد روش ارسال فعالی وجود ندارد.']);return $quotes; }
 public function selected(int $subtotal,int $weight,array $address,string $code):array{$quote=collect($this->quote($subtotal,$weight,$address,$code))->first();if(!$quote)throw ValidationException::withMessages(['shipping_method'=>'روش ارسال انتخاب‌شده برای این مقصد معتبر نیست.']);return $quote;}
}
